// One lead shape for every source: website, app, Meta lead ads, Google ads, portals.
const cfg = $('Config').first().json;
const cc = String(cfg.DEFAULT_COUNTRY_CODE || '91');
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  let digits = String(b.phone || b.mobile || b.whatsapp || b.contact_number || '').replace(/\D/g, '');
  digits = digits.replace(/^0+/, '');
  const local = digits.length > 10 ? digits.slice(-10) : digits;
  const wa_id = digits.length > 10 ? digits : (local ? cc + local : '');
  const now = new Date().toISOString();
  out.push({ json: {
    lead_id: 'L' + Date.now() + Math.floor(Math.random() * 900 + 100),
    created_at: now,
    name: String(b.name || b.full_name || b.lead_name || 'there').trim(),
    phone: local,
    wa_id: wa_id,
    phone_e164: wa_id ? '+' + wa_id : '',
    email: String(b.email || '').trim().toLowerCase(),
    source: b.source || b.platform || b.utm_source || 'website',
    campaign: b.campaign || b.utm_campaign || '',
    project: String(b.project || b.property || cfg.DEFAULT_PROJECT).trim(),
    budget: b.budget || b.budget_range || '',
    configuration: b.configuration || b.bhk || '',
    timeline: b.timeline || b.possession || '',
    message: b.message || b.notes || b.enquiry || '',
    status: 'New',
    owner: '',
    touch_count: 1,
    last_touch: now,
    last_action: 'LEAD_CAPTURED'
  } });
}
return out;

// Keep the original lead_id / created_at when this phone already exists in the CRM.
const lead = $('Normalise Lead').first().json;
const cfg = $('Config').first().json;
const row = ($json && $json.phone) ? $json : {};
const returning = !!row.phone;
const project = (lead.project && lead.project !== 'Not specified') ? lead.project : (row.project || cfg.DEFAULT_PROJECT);
const merged = {
  ...lead,
  lead_id: row.lead_id || lead.lead_id,
  created_at: row.created_at || lead.created_at,
  email: lead.email || row.email || '',
  owner: row.owner || '',
  project: project,
  is_returning: returning,
  touch_count: Number(row.touch_count || 0) + 1,
  status: returning ? (row.status || 'Re-enquiry') : 'New'
};
merged.welcome_header = ('Welcome to ' + cfg.COMPANY_NAME).slice(0, 60);
merged.welcome_body = 'Hi ' + merged.name + ' \uD83D\uDC4B\n\nWelcome to ' + cfg.COMPANY_NAME + ' - thanks for your interest in *' + project + '*.\n\nI can send you the full details and photos, the brochure PDF, or book a site visit at a time that suits you.\n\nTap a button below to continue.';
merged.welcome_footer = (returning ? 'Good to hear from you again' : 'We reply within minutes').slice(0, 60);
return [{ json: merged }];

