// Turns any inbound payload (WhatsApp Cloud API, or the local /simulate webhook)
// into: { wa_id, phone, name, action, action_arg, text }
// action is one of VIEW_DETAILS | DOWNLOAD_BROCHURE | BOOK_VISIT | SLOT | TEXT
const parsePayload = (raw) => {
  const s = String(raw || '');
  const parts = s.split('|');
  return { action: (parts.shift() || 'TEXT').toUpperCase(), arg: parts.join('|') };
};
const guessFromText = (t) => {
  const s = t.toLowerCase();
  if (/brochure|pdf|catalog/.test(s)) return 'DOWNLOAD_BROCHURE';
  if (/visit|site|book|schedule|appointment|tour/.test(s)) return 'BOOK_VISIT';
  if (/detail|price|rate|photo|pic|image|floor|info/.test(s)) return 'VIEW_DETAILS';
  return 'TEXT';
};
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // --- local test harness -------------------------------------------------
  const t = j.body || j;
  if (!j.entry && !j.messages && !j.changes && (t.action || t.text)) {
    const d = String(t.phone || t.wa_id || '').replace(/\D/g, '');
    const p = parsePayload(t.action || 'TEXT');
    out.push({ json: { channel: 'test', wa_id: d, phone: d.slice(-10), name: t.name || 'there', action: t.action ? p.action : guessFromText(String(t.text || '')), action_arg: t.action_arg || p.arg, text: t.text || '', wa_message_id: '' } });
    continue;
  }
  // --- WhatsApp Cloud API -------------------------------------------------
  const entry = (j.entry && j.entry[0]) || j;
  let value = (entry.changes && entry.changes[0] && entry.changes[0].value) || entry;
  if (!value.messages && j.from && j.type) value = { messages: [j], contacts: [] };
  if (!value.messages || !value.messages.length) continue; // delivery receipts / status callbacks
  const contact = (value.contacts && value.contacts[0]) || {};
  for (const m of value.messages) {
    let action = 'TEXT', arg = '', text = '';
    if (m.type === 'interactive') {
      const ir = m.interactive || {};
      const reply = ir.button_reply || ir.list_reply || {};
      text = reply.title || '';
      const p = parsePayload(reply.id);
      action = p.action; arg = p.arg;
    } else if (m.type === 'button') {
      const btn = m.button || {};
      text = btn.text || '';
      const p = parsePayload(btn.payload);
      action = p.action; arg = p.arg;
    } else if (m.type === 'text') {
      text = (m.text && m.text.body) || '';
      action = guessFromText(text);
    } else {
      text = '[' + m.type + ']';
    }
    const wa = String(m.from || '').replace(/\D/g, '');
    out.push({ json: { channel: 'whatsapp', wa_id: wa, phone: wa.slice(-10), name: (contact.profile && contact.profile.name) || 'there', action, action_arg: arg, text, wa_message_id: m.id || '' } });
  }
}
return out;

// Attach the CRM row to the inbound message. A WhatsApp-first contact with no CRM
// row still gets a lead_id here, so the next node creates the row.
const msg = $('Parse Inbound Message').first().json;
const cfg = $('Config').first().json;
const row = ($json && $json.phone) ? $json : {};
const now = new Date().toISOString();
return [{ json: {
  ...msg,
  lead_id: row.lead_id || ('L' + Date.now() + Math.floor(Math.random() * 900 + 100)),
  created_at: row.created_at || now,
  name: (row.name && row.name !== 'there') ? row.name : msg.name,
  email: row.email || '',
  source: row.source || 'whatsapp',
  project: (row.project && row.project !== 'Not specified') ? row.project : cfg.DEFAULT_PROJECT,
  status: row.status || 'Engaged',
  touch_count: Number(row.touch_count || 0) + 1,
  in_crm: !!row.phone
} }];

// Build every string the reply nodes need, from the Projects row (with safe fallbacks).
const lead = $('Resolve Lead').first().json;
const cfg = $('Config').first().json;
const p = ($json && $json.project_name) ? $json : {};
const g = (k, d) => (p[k] !== undefined && String(p[k]).trim() !== '') ? String(p[k]).trim() : d;
const project = g('project_name', lead.project);
const images = [g('image_1', ''), g('image_2', ''), g('image_3', '')].filter(Boolean);
const tagline = g('tagline', '');
const details_text = [
  '*' + project + '*' + (tagline ? ' - ' + tagline : ''),
  '',
  '\uD83D\uDCCD ' + g('location', 'Location shared on request'),
  '\uD83D\uDCB0 ' + g('price_range', 'Price on request'),
  '\uD83C\uDFE0 ' + g('configurations', 'Configurations on request') + (g('carpet_area', '') ? ' | ' + g('carpet_area', '') : ''),
  '\uD83D\uDD11 Possession: ' + g('possession', 'On request'),
  '\uD83D\uDCC4 RERA: ' + g('rera', 'On request'),
  '',
  '\u2728 ' + g('amenities', 'Clubhouse, gym, kids play area, landscaped gardens')
].join('\n').slice(0, 1000);
const now = new Date().toISOString();
return [{ json: {
  ...lead,
  project,
  details_text,
  images,
  image_count: images.length,
  brochure_url: g('brochure_url', ''),
  brochure_name: (project.replace(/[^A-Za-z0-9 ]/g, '').trim().replace(/\s+/g, '-') || 'brochure') + '.pdf',
  maps_link: g('maps_link', ''),
  address: g('address', g('location', '')),
  price_range: g('price_range', 'Price on request'),
  site_office_contact: g('site_office_contact', cfg.SALES_MANAGER_WHATSAPP),
  details_sent: lead.action === 'VIEW_DETAILS' ? now : '',
  brochure_sent: lead.action === 'DOWNLOAD_BROCHURE' ? now : '',
  menu_footer: cfg.COMPANY_NAME.slice(0, 60)
} }];

// One item per project photo, or a single empty item when the Projects row has none.
const c = $('Build Context').first().json;
if (!c.images || !c.images.length) return [{ json: { has_image: false, image_url: '', caption: '' } }];
return c.images.map((url, i) => ({ json: {
  has_image: true,
  image_url: url,
  caption: i === 0 ? (c.project + ' - ' + c.price_range).slice(0, 1000) : ''
} }));

